INSERT INTO `outbox` VALUES (1,1652319875,5,'post','{\"text\":\"📌 <b>vpsmincom</b>\\n👤 Thang Nguyen Huu · 🕒 14:35 17/10\\n────────────\\ncần thuê 150-200 proxy tĩnh hoặc datacenter Việt, us share giá rẻ càng rẻ càng tốt thuê lâu dài\",\"reply_markup\":{\"inline_keyboard\":[[{\"text\":\"🔗 Mở bài viết\",\"url\":\"https://www.facebook.com/groups/vpsmincom/permalink/2660789991107617/\"}],[{\"text\":\"🚫 Đánh dấu seller\",\"callback_data\":\"sp:5\"}]]}}','sent',1,0,NULL,7,NULL,'2026-10-18 02:51:04','2026-10-18 02:51:13'),(2,1652319875,6,'post','{\"text\":\"📌 <b>vpsmincom</b>\\n👤 Hoàng Công Minh · 🕒 14:52 17/10\\n────────────\\nMua tài khoản suftshark giá rẻ có ai bán không ạ\",\"reply_markup\":{\"inline_keyboard\":[[{\"text\":\"🔗 Mở bài viết\",\"url\":\"https://www.facebook.com/groups/vpsmincom/permalink/2660802004439749/\"}],[{\"text\":\"🚫 Đánh dấu seller\",\"callback_data\":\"s:100006167734806\"}]]}}','sent',1,0,NULL,8,NULL,'2026-10-18 02:51:04','2026-10-18 02:51:16'),(3,1652319875,7,'post','{\"text\":\"📌 <b>vpsmincom</b>\\n👤 Khanh Cao · 🕒 16:07 17/10\\n────────────\\nBên em có Рrоху v4,v6 xoay, tĩnh sạch HƠN 50 QUỐC GIA gіá siêu rẻ không giới hạn băng thông chỉ từ 5.000đ 1 tháng.\\n\\nVPS hơn 30 quốc gia chuyên deploy server web/app/treo game/treo chrome/treo bot/nuôi nick GIÁ CHỈ TỪ 29K 1 THÁNG\\n\\nChip xeon platinum/ gold siêu mạnh mẽ\\n\\nBăng thông không giới hạn, tốc độ mạng 1000mbps\\n\\nIP riêng, cam kết uptime ~ 100%\\n\\nWebsite có full quyền quản trị bật/tắt/cài hệ điều hành/ đổi mật khẩu\\n\\nZalo: 0812.134.124\\n\\nTelegram: [@cloudexvn]\\n\\nMua hàng tự động tại cloudex(.)vn\",\"reply_markup\":{\"inline_keyboard\":[[{\"text\":\"🔗 Mở bài viết\",\"url\":\"https://www.facebook.com/groups/vpsmincom/permalink/2660855994434350/\"}],[{\"text\":\"🚫 Đánh dấu seller\",\"callback_data\":\"sp:7\"}]]}}','sent',1,0,NULL,9,NULL,'2026-10-18 02:51:04','2026-10-18 02:51:18'),(4,1652319875,8,'post','{\"text\":\"📌 <b>vpsmincom</b>\\n👤 Tanny Proxy-vps · 🕒 23:24 17/10\\n────────────\\nBên em cung cấp <b>Proxy IPv4/IPv6 và VPS quốc tế</b> giá rẻ.\\n\\n🔹 Proxy xoay, proxy tĩnh, hơn 50 quốc gia, từ <b>5.000đ/tháng</b>.\\n🔹 VPS hơn 30 quốc gia, từ <b>29.000đ/tháng</b>.\\n🔹 CPU Xeon Gold/Platinum, tốc độ mạng lên đến 1Gbps.\\n🔹 Hỗ trợ bật/tắt VPS, cài lại hệ điều hành, đổi mật khẩu trực tiếp trên website.\\n\\nPhù hợp chạy web/app, Chrome, bot, treo game và nhiều nhu cầu khác.\\n\\n📱 Zalo: 0373.196.713\\n✈️ Telegram: @proxyvpsvn\\n🌐 Website: https://proxyvps.vn\\n\\n<b>Giá rẻ, dễ sử dụng, đặt hàng tự động trên website!</b>\",\"reply_markup\":{\"inline_keyboard\":[[{\"text\":\"🔗 Mở bài viết\",\"url\":\"https://www.facebook.com/groups/vpsmincom/permalink/2661221751064441/\"}],[{\"text\":\"🚫 Đánh dấu seller\",\"callback_data\":\"s:100090179152479\"}]]}}','sent',1,0,NULL,10,NULL,'2026-10-18 02:51:04','2026-10-18 02:51:20'),(5,1652319875,9,'post','{\"text\":\"📌 <b>J2TEAM Community</b>\\n👤 Trần Bình ✓⃝ · 🕒 16:06 17/10\\n────────────\\n#j2team_share\\nMình vừa làm Dot Ads, một extension hỗ trợ chặn quảng cáo trên Safari, với giao diện tối giản, thao tác nhanh và nhiều tùy chọn kiểm soát quảng cáo, popup cũng như chuyển hướng không mong muốn.\\n\\nTính năng nổi bật ✨\\n• Bật/tắt nhanh: Dot xanh nhấp nháy là bật, dot xám là tắt.\\n• Chặn quảng cáo tự động: Ẩn quảng cáo, banner, popup và nội dung nổi.\\n• Chặn phần tử: Nhấn giữ 3 giây để xem và sao chép selector.\\n• Bộ lọc tùy chỉnh: Chặn theo selector, class, ID, văn bản, URL/domain.\\n• Chặn popup &amp; chuyển hướng: Hạn chế tab lạ và website tự mở.\\n• Ẩn khung quảng cáo: Loại bỏ cả khung chứa, viền và nút đóng.\\n• Bộ lọc linh hoạt: Áp dụng toàn cục hoặc theo từng website.\\n• Lưu cấu hình: Ghi nhớ bộ lọc khi truy cập lại.\\n• Sao lưu &amp; khôi phục: Xuất/nhập JSON, hỗ trợ gộp hoặc thay thế quy tắc.\\n\\nDot Ads hướng đến trải nghiệm duyệt web gọn gàng, dễ sử dụng và cho phép người dùng chủ động kiểm soát những gì xuất hiện trên trang.\\n\\nDot Ads – Chặn quảng cáo với một chạm! Link extension và hướng dẫn mình sẽ để dưới phần comment!\",\"reply_markup\":{\"inline_keyboard\":[[{\"text\":\"🔗 Mở bài viết\",\"url\":\"https://www.facebook.com/groups/j2team.community/permalink/3213041829027915/\"}],[{\"text\":\"🚫 Đánh dấu seller\",\"callback_data\":\"s:100091902503211\"}]]}}','sent',1,0,NULL,11,NULL,'2026-10-18 02:56:41','2026-10-18 02:56:55'),(6,1652319875,10,'post','{\"text\":\"📌 <b>J2TEAM Community</b>\\n👤 Đào Việt Bách · 🕒 19:11 17/10\\n────────────\\nTối qua vừa ngồi nghĩ ra 10 cái prompt để test con Chatbot AI... \\nSáng ra thấy NVIDIA với FPT vứt cho hẳn 1 TRIỆU hồ sơ người dùng để test. Đúng là công nghệ đi trước con người 🤡\\n\\nNói ngắn gọn cho anh em AI/Dev nào chưa biết: Dataset Nemotron-Personas-Vietnam vừa được bump từ 100K lên hẳn 1 triệu bản ghi trên Hugging Face.\\n\\n✨ Điểm sướng:\\n- Không dính líu thông tin người thật (100% AI sinh ra dựa trên thống kê dân số VN 2024).\\n- Chi tiết tới tận 21 trường dữ liệu: từ độ tuổi, học vấn, nghề nghiệp cho đến sở thích, thói quen ăn uống, du lịch...\\n- Đủ mọi tầng lớp: từ Gen Z nghiện TikTok đến các bác U60 ít dùng công nghệ.\\n\\nDùng cái này test Agentic AI hay làm Red Teaming cho LLM thì bao phủ hết các ngóc ngách luôn, đỡ phải ngồi tự quay tay nghĩ scenario.\\n\\nĐấy cap thử cho anh em xem cái data chi tiết đến mức nào. Ai thích hàng ngon + miễn phí thì vào Hugging Face:\\n👉 https://huggingface.co/datasets/nvidia/Nemotron-Personas-Vietnam \\n\\nThả tim rồi clone về chạy thử đi anh em, tối về chém gió tiếp! 🚀\\n**#AI (https://www.facebook.com/hashtag/ai?__cft__[0]=AZi-5VeNzt5HlN3LlmszPpsG4UXVtS2GiG7KJq1YsaYwh39UV_gqnbM3SZH_CbEtZuhzXphqFmZMtkF39P9QbFij2wiVVBLjCrKUGP5Icz3uwXKcPAivI8Bvqny5TBzTet0LAVVMOM3TqaNhfIj0&amp;__tn__=*NK-R)<b> </b>#AgenticAI (https://www.facebook.com/hashtag/agenticai?__cft__[0]=AZi-5VeNzt5HlN3LlmszPpsG4UXVtS2GiG7KJq1YsaYwh39UV_gqnbM3SZH_CbEtZuhzXphqFmZMtkF39P9QbFij2wiVVBLjCrKUGP5Icz3uwXKcPAivI8Bvqny5TBzTet0LAVVMOM3TqaNhfIj0&amp;__tn__=*NK-R)<b> </b>#LLM (https://www.facebook.com